SELECT p.category,o.year,o.discount_band,COUNT(*) orders,SUM(o.net_revenue_cents)/100.0 revenue,SUM(o.contribution_cents)/100.0 contribution,1.0*SUM(o.contribution_cents)/NULLIF(SUM(o.net_revenue_cents),0) margin,1.0*SUM(o.returned_units)/SUM(o.quantity) unit_return_rate FROM orders o JOIN products p USING(product_id) GROUP BY p.category,o.year,o.discount_band ORDER BY p.category,o.year,o.discount_band
